    async fn write_reservation(
        &self,
        tx: &mut Transaction<'_, Postgres>,
        attempt: &ReservationAttempt<'_>,
        ready: ReadyReservation,
    ) -> AppResult<End<Reserving>> {
        let ReservationAttempt {
            request,
            entry,
            pending,
            mode,
            ..
        } = *attempt;
        let ReadyReservation {
            action,
            policy,
            window,
            provider,
        } = ready;
        if matches!(mode, ReserveMode::Prepare) {
            if matches!(
                self.marker_state_on(tx, request, &action, &provider)
                    .await?,
                super::action_receipts::RemoteMarkerState::Refused
            ) {
                return Ok(End::Rollback(Reserving::Refused(
                    RemoteReservationResult::PossibleDispatchExists,
                )));
            }
            return Ok(End::Rollback(Reserving::Prepared(Box::new(action), window)));
        }
        let Some(marker) = self
            .marker_on(tx, request, &action, policy, &provider)
            .await?
        else {
            return Ok(End::Rollback(Reserving::Refused(
                RemoteReservationResult::PossibleDispatchExists,
            )));
        };
        if !Self::reserve_entry_on(tx, request, marker, entry).await? {
            return Ok(End::Rollback(Reserving::Refused(
                RemoteReservationResult::PossibleDispatchExists,
            )));
        }
        // Held before COMMIT is sent, so an ambiguous acknowledgement can still hand
        // back this same reservation once the resolution proves it committed.
        *pending.lock().map_err(|_| conflict())? = Some(RemoteReservation {
            marker,
            entry,
            action,
            request: request.clone(),
            window,
            provider,
        });
        Ok(End::Commit(Reserving::Reserved))
    }
}

#[async_trait]
impl<A: SqlActionAuthority, L: SqlLocalAction> RemoteDispatch for PostgresActionDispatch<A, L> {
    async fn reserve_remote(
        &self,
        request: &ActionDispatchRequest,
        contract: Option<&ProviderReplayContract>,
    ) -> AppResult<RemoteReservationResult> {
        // Box the additional preparation seam to keep the native supervisor frame bounded.
        Box::pin(self.reserve_for(request, contract, ReserveMode::Dispatch)).await
    }

    async fn enter_remote(&self, reservation: RemoteReservation) -> AppResult<RemoteEntry> {
        let request = &reservation.request;
        let bound = WriteBound::read_only("action.enter_remote", request.lease);
        let window = bound.read(Box::pin(async {
            let started = bound.started();
            let mut conn = bound.acquire(self.persistence.pool()).await?;
            let mut tx = bound.begin(&mut conn).await?;
            let window = async {
                let AuthorizedAction {
                    approval_required: protected,
                    ..
                } = self.authorize_on(&mut tx, request, bound.server_timeout()).await?;
                token_budget::require_progression(&mut tx, request.fence.scope).await?;
                if protected {
                    return Err(missing());
                }
                Self::verify_entry_on(
                    &mut tx,
                    request,
                    reservation.marker,
                    reservation.entry,
                    &reservation.action,
                    &reservation.provider,
                )
                .await?;
                let allowed: bool = sqlx::query_scalar("SELECT NOT workflow_action_has_evidence_conflict($1,$2) AND NOT EXISTS(SELECT 1 FROM workflow_action_evidence WHERE company_id=$1 AND invocation_id=$3 AND disposition='applied') AND (NOT EXISTS(SELECT 1 FROM workflow_action_evidence_consumptions WHERE company_id=$1 AND remote_entry_id=$4) OR workflow_action_not_applied_available($1,$3,$4) IS NOT NULL)")
                    .bind(request.scope().company.as_uuid()).bind(request.scope().execution.as_uuid())
                    .bind(request.subject.invocation.as_uuid()).bind(reservation.entry).fetch_one(&mut *tx).await?;
                if !allowed { return Err(conflict()); }
                lease::live_window(&mut tx, request.fence, started)
                    .await?
                    .ok_or_else(conflict)
            }
            .await;
            // Read-only: ROLLBACK needs no synchronous flush and leaves nothing ambiguous.
            bound.roll_back(tx, window).await
        }))
        .await?;
        Ok(RemoteEntry {
            marker: reservation.marker,
            entry: reservation.entry,
            request: reservation.request,
            action: reservation.action,
            provider: reservation.provider,
            deadline: window
                .expires
                .min(window.run_deadline)
                .min(reservation.window.expires)
                .min(reservation.window.run_deadline),
        })
    }

pub(super) async fn return_authorized(&self, entry: &RemoteEntry) -> AppResult<bool> {
    let bound = WriteBound::read_only("action.return_authorized", entry.request.lease);
    bound
        .read(Box::pin(async {
            let started = Instant::now();
            let mut conn = bound.acquire(self.persistence.pool()).await?;
            let mut tx = bound.begin(&mut conn).await?;
            let window = async {
                // Company/principal before run, including this ownership-only precheck.
                let actor =
                    action_authority::prelock_on(&mut tx, entry.request.scope()).await?;
                // Known ownership loss suppresses output; operational failures remain errors.
                if !lease::lock_fence(&mut tx, entry.request.fence, bound.server_timeout())
                    .await?
                    || lease::live_window(&mut tx, entry.request.fence, started)
                        .await?
                        .is_none()
                {
                    return Ok(None);
                }
                let authorized = self
                    .authorize_prelocked_on(
                        &mut tx,
                        &entry.request,
                        bound.server_timeout(),
                        actor,
                    )
                    .await?;
                if authorized.approval_required
                    || action_uncertainty::conflicted_on(&mut tx, entry.request.scope()).await?
                {
                    return Ok(None);
                }
                lease::live_window(&mut tx, entry.request.fence, started).await
            }
            .await;
            // Read-only: ROLLBACK on every path, including a known ownership loss, so the
            // run lock lock_fence took is released before the caller sees `false`.
            let window = bound.roll_back(tx, window).await?;
            Ok::<_, AppError>(
                window.is_some_and(|w| {
                    Instant::now() < w.expires && Instant::now() < w.run_deadline
                }),
            )
        }))
        .await
}

struct HostDispatchAuthority {
    persistence: PostgresPersistence,
    request: ActionDispatchRequest,
    expected: AuthorizedInvocation,
    owner: Uuid,
    kind: BindingKind,
}
impl HostDispatchAuthority {
    async fn current(&self, tx: &mut Transaction<'_, Postgres>) -> AppResult<FrozenAction> {
        let actor = action_authority::prelock_accounts_on(
            tx,
            self.request.scope(),
            Some(WorkflowActor::authenticated(self.owner)?),
        )
        .await?;
        let dispatch = PostgresActionDispatch::new(
            self.persistence.clone(),
            IntegrationResource(self.kind),
            NoLocal,
        );
        let authorized = dispatch
            .authorize_prelocked_on(tx, &self.request, Duration::from_secs(2), actor)
            .await?;
        if authorized.approval_required
            || authorized.action.request().context.origin != ToolCallOrigin::Workflow
        {
            return Err(missing());
        }
        let facts = http::runtime::facts(tx, self.request.scope()).await?;
        let step: String = sqlx::query_scalar(
            "SELECT step_id FROM workflow_executions WHERE company_id=$1 AND run_id=$2 AND id=$3",
        )
        .bind(self.request.scope().company.as_uuid())
        .bind(self.request.scope().run.as_uuid())
        .bind(self.request.scope().execution.as_uuid())
        .fetch_one(&mut **tx)
        .await?;
        let step = StepId::parse(step).map_err(|_| invalid())?;
        let definition = facts
            .bundle
            .compiled()
            .graph()
            .definition()
            .steps
            .get(&step)
            .ok_or_else(missing)?;
        let permitted = match self.kind {
            BindingKind::Http => {
                matches!(definition.step_type.as_str(), "http.request" | "tool.call")
            }
            BindingKind::Mcp => definition.step_type.as_str() == "mcp.call",
        };
        if !permitted {
            return Err(missing());
        }
        let member:Option<Uuid>=sqlx::query_scalar("SELECT member.user_id FROM company_members AS member JOIN principals AS principal ON principal.company_id=member.company_id AND principal.user_id=member.user_id WHERE member.company_id=$1 AND member.user_id=$2 AND principal.kind='person' FOR SHARE OF member,principal")
            .bind(self.request.scope().company.as_uuid()).bind(self.owner).fetch_optional(&mut **tx).await?;
        if member.is_none() {
            return Err(missing());
        }
        Ok(authorized.action)
    }
}
#[async_trait]
impl DispatchAuthority for HostDispatchAuthority {
    async fn check(
        &self,
        invocation: &AuthorizedInvocation,
        module: &dyn CredentialDispatchGate,
    ) -> integration::IntegrationResult<()> {
        if serde_json::to_value(invocation).map_err(|_| integration::IntegrationError::Invalid)?
            != serde_json::to_value(&self.expected)
                .map_err(|_| integration::IntegrationError::Invalid)?
            || invocation.deadline <= Utc::now()
        {
            return Err(integration::IntegrationError::Denied);
        }
        let mut tx = http::begin_http(&self.persistence)
            .await
            .map_err(host_error)?;
        let current = self.current(&mut tx).await.map_err(host_error)?;
        if digest(current.operation_digest().as_str()).map_err(host_error)?
            != invocation.request_digest
            || current.request().arguments != *invocation.arguments.value()
            || current.request().operation_key.as_str() != invocation.operation.as_str()
            || current.request().context.integration.as_ref() != Some(&invocation.authorization)
            || operation_target(&current, self.kind).map_err(host_error)? != invocation.target
        {
            return Err(integration::IntegrationError::Denied);
        }
        module
            .check(
                invocation,
                HostAuthorityFacts {
                    owner_is_member: true,
                    connection_enabled: true,
                    action_authorized: true,
                    server_created_provenance: true,
                    kind: self.kind.purpose(),
                    connection_revision: invocation.authorization.connection_revision,
                    catalog_revision: invocation.authorization.catalog_revision,
                },
            )
            .await?;
        // Row locks preserve the checked identities, but time still passes while
        // the module waits. Match ordinary remote entry's final live-window check.
        if invocation.deadline <= Utc::now()
            || super::lease::live_window(&mut tx, self.request.fence, tokio::time::Instant::now())
                .await
                .map_err(host_error)?
                .is_none()
        {
            return Err(integration::IntegrationError::Denied);
        }
        tx.rollback()
            .await
            .map_err(|_| integration::IntegrationError::Storage)?;
        Ok(())
    }

pub(in crate::adapters::persistence::workflow) async fn already_recorded_on(
    db: &mut PgConnection,
    request: &ActionDispatchRequest,
) -> AppResult<bool> {
    let scope = request.fence.scope;
    Ok(sqlx::query_scalar("SELECT EXISTS(SELECT 1 FROM workflow_decisions WHERE company_id=$1 AND execution_id=$2 AND action_invocation_id=$3) OR EXISTS(SELECT 1 FROM workflow_action_dispatches WHERE company_id=$1 AND execution_id=$2 AND invocation_id=$3)")
        .bind(scope.company.as_uuid()).bind(scope.execution.as_uuid()).bind(request.subject.invocation.as_uuid()).fetch_one(db).await?)
}

enum Purpose<'a> {
    Effect,
    Reply,
    Dispatch {
        request: &'a ActionDispatchRequest,
        notices: Option<&'a DecisionNotices>,
    },
    Message {
        request: &'a ActionDispatchRequest,
        plan: &'a MessagePlan,
        notices: Option<&'a DecisionNotices>,
    },
}

#[derive(PartialEq, Eq)]
pub(in crate::adapters::persistence::workflow) struct ActorAccountHints {
    actor: Uuid,
    requester: Option<WorkflowActor>,
    reviewer: Option<WorkflowActor>,
}

impl ActorAccountHints {
    pub(in crate::adapters::persistence::workflow) fn actor(&self) -> AppResult<WorkflowActor> {
        WorkflowActor::authenticated(self.actor)
    }

    pub(in crate::adapters::persistence::workflow) fn users(
        &self,
    ) -> impl Iterator<Item = Uuid> + '_ {
        std::iter::once(self.actor)
            .chain(self.requester.map(WorkflowActor::user_id))
            .chain(self.reviewer.map(WorkflowActor::user_id))
    }
}

#[derive(PartialEq, Eq)]
enum Source {
    NotApplicable,
    Reply(super::super::approval_accounts::ApprovalAccounts),
    Dispatch {
        approval: ActionApprovalAccounts,
        escalation: Option<super::super::escalations::CommandTarget>,
    },
    Message {
        recipients: MessageSource,
        approval: ActionApprovalAccounts,
    },
}

#[derive(PartialEq, Eq)]
enum MessageSource {
    FreshMessage(Vec<Uuid>),
    RecordedMessage,
}

impl Source {
    fn users(&self) -> impl Iterator<Item = Uuid> + '_ {
        let (recipients, approval) = match self {
            Self::NotApplicable | Self::Reply(_) => (&[][..], None),
            Self::Dispatch { approval, .. } => (&[][..], Some(approval)),
            Self::Message {
                recipients,
                approval,
            } => (
                match recipients {
                    MessageSource::FreshMessage(users) => users.as_slice(),
                    MessageSource::RecordedMessage => &[],
                },
                Some(approval),
            ),
        };
        let reply = match self {
            Self::Reply(approval) => Some(approval),
            _ => None,
        };
        let escalation = match self {
            Self::Dispatch {
                escalation: Some(target),
                ..
            } => Some(target.account),
            _ => None,
        };
        recipients
            .iter()
            .copied()
            .chain(approval.into_iter().flat_map(|hint| hint.users()))
            .chain(reply.into_iter().flat_map(|hint| hint.users()))
            .chain(escalation)
    }

    fn recorded(&self) -> bool {
        matches!(
            self,
            Self::Dispatch {
                approval: ActionApprovalAccounts::Recorded,
                ..
            } | Self::Message {
                recipients: MessageSource::RecordedMessage,
                ..
            }
        )
    }
}

async fn source_on(
    db: &mut PgConnection,
    scope: ActionScope,
    purpose: Purpose<'_>,
) -> AppResult<Source> {
    match purpose {
        Purpose::Effect => Ok(Source::NotApplicable),
        Purpose::Reply => Ok(Source::Reply(
            super::super::approval_accounts::load_on(db, scope).await?,
        )),
        Purpose::Dispatch { request, notices } => {
            let approval = super::super::approval_accounts::action_on(db, request, notices).await?;
            let escalation = if matches!(approval, ActionApprovalAccounts::Recorded) {
                None
            } else {
                super::super::escalation_tools::target_hint_on(db, request).await?
            };
            Ok(Source::Dispatch {
                approval,
                escalation,
            })
        }
        Purpose::Message {
            request,
            plan,
            notices,
        } => {
            let recipients = message_source_on(db, request, plan).await?;
            let approval = match recipients {
                MessageSource::RecordedMessage => ActionApprovalAccounts::Recorded,
                _ => super::super::approval_accounts::action_on(db, request, notices).await?,
            };
            Ok(Source::Message {
                recipients,
                approval,
            })
        }
    }
}

pub(super) async fn action_on(
    db: &mut PgConnection,
    request: &crate::application::workflow::actions::ActionDispatchRequest,
    notices: Option<&DecisionNotices>,
) -> AppResult<ActionApprovalAccounts> {
    if decisions::approvals::already_recorded_on(db, request).await? {
        return Ok(ActionApprovalAccounts::Recorded);
    }
    if notices.is_none() {
        return Ok(ActionApprovalAccounts::NotApplicable);
    }
    let scope = request.fence.scope;
    let configuration: Option<Value> = sqlx::query_scalar::<_, Option<Value>>(
        "SELECT frozen_inputs->'approval' FROM workflow_executions \
         WHERE company_id=$1 AND run_id=$2 AND id=$3",
    )
    .bind(scope.company.as_uuid())
    .bind(scope.run.as_uuid())
    .bind(scope.execution.as_uuid())
    .fetch_optional(&mut *db)
    .await?
    .flatten();
    let Some(configuration) = configuration else {
        return Ok(ActionApprovalAccounts::NotApplicable);
    };
    let Ok((selectors, _)) = reviewer_deadline(&configuration) else {
        return Ok(ActionApprovalAccounts::Unavailable(configuration));
    };
    let principals = match reviewer_resolution::resolve_on(db, scope, &selectors).await {
        Ok(principals) => principals,
        Err(AppError::BadRequest(_) | AppError::WorkflowRole(_)) => {
            return Ok(ActionApprovalAccounts::Unavailable(configuration));
        }
        Err(error) => return Err(error),
    };
    let mappings = mapped_on(db, scope.company, &principals).await?;
    Ok(ActionApprovalAccounts::Pending {
        configuration,
        principals,
        mappings,
    })
}
